INSERT INTO repo_kprs (kpr_id, name, domain, discipline, principle_type, principle_granularity, definition, scope, core_ideas, semantic_description, keywords_synonyms, status) VALUES ('KPR_000001', 'Pigeonhole Principle', 'Engineering & Technology', 'Computer Science; Discrete Mathematics', 'Principle', 'Atomic', 'A counting principle stating that if more objects are assigned to fewer containers, at least one container must contain more than one object.', 'Applies to finite counting and allocation arguments in which the number of objects exceeds the number of available categories or containers; it does not by itself identify which container contains the repeated objects.', 'Counting; cardinality comparison; unavoidable repetition', 'A foundational counting principle that converts a simple cardinality inequality into a guaranteed existence result. It is used in combinatorics, discrete mathematics, hashing arguments, and allocation reasoning.', 'Pigeonhole principle; Dirichlet principle; box principle', 'Active'), ('KPR_000002', 'Principle of Mathematical Induction', 'Engineering & Technology', 'Computer Science; Discrete Mathematics', 'Principle', 'Atomic', 'A proof principle in which a proposition is established for a base case and then shown to propagate from an arbitrary valid case to the next case.', 'Applies to statements indexed over an inductive domain such as the natural numbers; the induction step must explicitly establish the implication from the assumed case to the successor case.', 'Base case; inductive hypothesis; inductive step; well-founded progression', 'Mathematical induction establishes universal statements over inductively structured domains by combining a valid base case with a valid propagation step.', 'Mathematical induction; induction principle', 'Active'), ('KPR_000003', 'Equivalence-Class Principle', 'Engineering & Technology', 'Computer Science; Discrete Mathematics', 'Principle', 'Atomic', 'The principle that an equivalence relation partitions a set into disjoint equivalence classes, with every element belonging to exactly one class.', 'Applies when the relation is reflexive, symmetric, and transitive. It should not be generalized to arbitrary relations.', 'Reflexivity; symmetry; transitivity; partitioning', 'An equivalence relation induces a partition of a set into classes of mutually equivalent elements. The resulting quotient structure supports classification and abstraction.', 'Equivalence-class principle; quotient-set principle', 'Active'), ('KPR_000004', 'Conservation of Mass', 'Engineering & Technology', 'Chemical Engineering; Civil Engineering; Mechanical Engineering', 'Conservation Principle', 'Atomic', 'The principle that mass is conserved in a system except where the system boundary permits mass to enter or leave, with accumulation equal to inflow minus outflow plus any specified generation or consumption terms.', 'Applies to defined system or control-volume boundaries and requires consistent accounting of all relevant mass streams; chemical reaction changes species composition but does not destroy total mass in ordinary engineering balances.', 'Mass balance; accumulation; inflow; outflow; control volume', 'Conservation of mass provides the fundamental balance relation used to formulate material balances in fluid systems, process calculations, reactors, and environmental systems.', 'Mass conservation; mass-balance principle', 'Active'), ('KPR_000005', 'Conservation of Energy', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering; Civil Engineering', 'Conservation Principle', 'Atomic', 'The principle that energy cannot be created or destroyed; for a defined system or control volume, energy changes are accounted for through transfers such as heat and work and, where applicable, mass flow.', 'Applies to properly defined system boundaries and consistent energy accounting. It does not imply that energy quality or ability to perform useful work is conserved.', 'Energy balance; heat; work; internal energy; mass-energy transfer', 'Conservation of energy provides the first-order accounting principle underlying energy balances across thermodynamics, fluid systems, heat transfer, and process engineering.', 'Energy conservation; first-law conservation principle', 'Active'), ('KPR_000006', 'Second Law of Thermodynamics', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering', 'Law', 'Atomic', 'The second law establishes the directionality of spontaneous thermodynamic processes and the non-decrease of total entropy for an isolated system.', 'Applies to thermodynamic processes and cycles subject to the stated system boundaries and equilibrium assumptions; it constrains achievable conversion efficiency and distinguishes reversible from irreversible processes.', 'Entropy; irreversibility; directionality; reversible limit; efficiency limit', 'The second law supplements energy conservation by imposing feasibility and direction constraints on thermodynamic processes.', 'Second law; entropy principle', 'Active'), ('KPR_000007', 'Newton''s Second Law of Motion', 'Engineering & Technology', 'Mechanical Engineering; Civil Engineering', 'Law', 'Atomic', 'The net external force on a body equals the time rate of change of its linear momentum; for constant mass, this reduces to force equal to mass times acceleration.', 'Applies in inertial reference frames and with forces defined consistently. The simple F = ma form assumes constant mass; variable-mass systems require momentum accounting.', 'Force; momentum; acceleration; inertial frame', 'Newton''s second law provides the governing dynamic relation connecting applied forces to translational motion and momentum change.', 'Newton''s second law; equation of motion', 'Active'), ('KPR_000008', 'Newton''s Third Law', 'Engineering & Technology', 'Mechanical Engineering; Civil Engineering', 'Law', 'Atomic', 'When two bodies interact, the force exerted by one on the other is accompanied by an equal-magnitude force exerted by the other in the opposite direction.', 'Applies to paired interaction forces between bodies; the forces act on different bodies and therefore should not be cancelled within the free-body diagram of a single body.', 'Action-reaction; interaction pair; force balance', 'Newton''s third law describes the paired nature of interaction forces and is fundamental to free-body analysis and contact-force reasoning.', 'Newton''s third law; action-reaction principle', 'Active'), ('KPR_000009', 'Hooke''s Law', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Constitutive Principle', 'Atomic', 'Within the linear elastic range of a material or idealized element, deformation is proportional to the applied load or stress is proportional to strain.', 'Applies only within the specified linear-elastic regime and under the assumptions of the adopted material model; it does not describe plastic or strongly nonlinear response.', 'Elasticity; proportionality; stiffness; stress-strain relation', 'Hooke''s law supplies the constitutive relation between stress and strain in the linear elastic regime and underlies stiffness calculations.', 'Hooke''s law; linear elasticity', 'Active'), ('KPR_000010', 'Principle of Superposition', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering; Electrical Engineering', 'Principle', 'Atomic', 'For a linear system, the response to a combination of independent inputs equals the sum of the responses to each input acting separately.', 'Requires linearity of the governing system over the range considered. It does not generally apply to nonlinear material behaviour, nonlinear circuits, or nonlinear dynamics.', 'Linearity; additive response; independent loading', 'Superposition allows complex linear responses to be decomposed into simpler component responses and then recombined.', 'Superposition principle; linear superposition', 'Active'), ('KPR_000011', 'Continuity Principle', 'Engineering & Technology', 'Civil Engineering; Chemical Engineering; Mechanical Engineering', 'Conservation Principle', 'Atomic', 'The continuity principle expresses conservation of mass through a control volume, relating mass accumulation to net mass flow across the boundary.', 'Applies to defined control volumes or streamtubes with consistent density, velocity, and area descriptions; simplified forms require the relevant steady-state and incompressibility assumptions.', 'Mass conservation; flux; accumulation; flow rate', 'The continuity principle is the mass-conservation foundation for fluid-flow analysis and pipe/network calculations.', 'Continuity equation; continuity principle', 'Active'), ('KPR_000012', 'Bernoulli Principle', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Principle', 'Atomic', 'For steady, incompressible flow along a streamline under the stated ideal-flow assumptions, pressure, elevation, and kinetic-energy terms satisfy a constant mechanical-energy relation.', 'The elementary form applies to steady, incompressible, inviscid flow along a streamline with no shaft work or heat-transfer contribution between the selected points; extended energy equations are required otherwise.', 'Pressure head; velocity head; elevation head; mechanical energy', 'Bernoulli''s principle is an energy relation for idealized fluid flow and provides a basis for interpreting pressure-velocity-elevation trade-offs.', 'Bernoulli equation; Bernoulli principle', 'Active'), ('KPR_000013', 'Darcy''s Law', 'Engineering & Technology', 'Civil Engineering', 'Law', 'Atomic', 'Darcy''s law relates the specific discharge through a porous medium to the hydraulic gradient and hydraulic conductivity under the conditions for which Darcy flow is valid.', 'Applies to laminar flow through porous media represented by an appropriate hydraulic conductivity and gradient; it is not a universal law for non-Darcy or highly inertial porous-media flow.', 'Hydraulic gradient; hydraulic conductivity; specific discharge; porous medium', 'Darcy''s law provides the constitutive relation used to quantify groundwater and porous-media flow.', 'Darcy law; Darcy''s equation', 'Active'), ('KPR_000014', 'Mohr-Coulomb Failure Criterion', 'Engineering & Technology', 'Civil Engineering', 'Criterion', 'Atomic', 'The Mohr-Coulomb criterion states that shear failure occurs when the mobilized shear stress reaches a resistance governed by effective normal stress, cohesion, and friction angle.', 'Applies as an idealized frictional failure criterion for soils and rocks within the assumptions of the selected effective-stress and strength model; it does not capture all nonlinear or strain-dependent failure behaviour.', 'Shear strength; effective stress; cohesion; friction angle', 'The criterion provides a simplified failure envelope for frictional geomaterials and supports bearing, slope, excavation, and foundation assessments.', 'Mohr-Coulomb criterion; Coulomb failure criterion', 'Active'), ('KPR_000015', 'Fourier''s Law of Heat Conduction', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering', 'Law', 'Atomic', 'Fourier''s law states that conductive heat flux is proportional to the negative temperature gradient, with thermal conductivity providing the proportionality factor.', 'Applies to conductive heat transfer within the assumptions of the constitutive model; thermal conductivity may depend on temperature, direction, material state, and microstructure.', 'Temperature gradient; thermal conductivity; conductive heat flux', 'Fourier''s law is the constitutive basis for conduction heat-transfer equations and thermal resistance formulations.', 'Fourier law; law of heat conduction', 'Active'), ('KPR_000016', 'Fick''s First Law', 'Engineering & Technology', 'Chemical Engineering; Mechanical Engineering', 'Law', 'Atomic', 'Fick''s first law relates diffusive flux to the negative concentration gradient for diffusion under conditions where the constitutive law is applicable.', 'Applies primarily to steady or quasi-steady diffusion representations with an appropriate concentration coordinate and constant or specified diffusivity; transient accumulation requires the second law.', 'Concentration gradient; diffusivity; diffusive flux', 'Fick''s first law provides the constitutive relation for molecular diffusion and mass-transfer calculations.', 'Fick''s first law; diffusion law', 'Active'), ('KPR_000017', 'Arrhenius Temperature Dependence', 'Engineering & Technology', 'Chemical Engineering', 'Constitutive Principle', 'Atomic', 'The Arrhenius relation represents the temperature dependence of a reaction-rate constant through an exponential dependence on inverse absolute temperature and activation energy.', 'Applies to reaction systems for which the Arrhenius representation is an adequate kinetic model over the stated temperature range; it is not a universal mechanistic explanation of all temperature effects.', 'Rate constant; activation energy; absolute temperature; exponential dependence', 'The Arrhenius relation connects temperature with kinetic rate constants and is widely used in reaction engineering and kinetic parameter estimation.', 'Arrhenius equation; Arrhenius relation', 'Active'), ('KPR_000018', 'Le Chatelier''s Principle', 'Engineering & Technology', 'Chemical Engineering', 'Principle', 'Atomic', 'When an equilibrium system is subjected to a change in conditions, its equilibrium composition shifts in the direction that tends to oppose the imposed change.', 'Applies to systems at or near chemical equilibrium under the specified perturbation; it predicts the direction of response rather than providing the complete quantitative equilibrium composition.', 'Equilibrium; perturbation; composition shift; temperature; pressure', 'Le Chatelier''s principle provides qualitative reasoning about the response of chemical equilibria to changes in operating conditions.', 'Le Chatelier principle; equilibrium-shift principle', 'Active'), ('KPR_000019', 'Law of Mass Action', 'Engineering & Technology', 'Chemical Engineering', 'Law', 'Atomic', 'At chemical equilibrium, the equilibrium composition is related to the activities or concentrations of reactants and products through an equilibrium constant for the specified reaction.', 'Applies to reactions represented under the adopted thermodynamic and concentration/activity convention; equilibrium constants depend on temperature and the chosen standard-state formulation.', 'Equilibrium constant; activities; concentrations; stoichiometry', 'The law of mass action provides the foundation for equilibrium-constant expressions and quantitative equilibrium calculations.', 'Mass-action law; law of mass action', 'Active'), ('KPR_000020', 'Ohm''s Law', 'Engineering & Technology', 'Electrical Engineering', 'Law', 'Atomic', 'For an ohmic element under specified conditions, voltage is proportional to current with resistance as the proportionality factor.', 'Applies to elements exhibiting approximately linear voltage-current behaviour over the operating range; many semiconductor and nonlinear devices do not obey a constant-resistance form.', 'Voltage; current; resistance; linear electrical behaviour', 'Ohm''s law is the constitutive relation for linear resistive electrical elements and is used in circuit analysis.', 'Ohm law; V-I relation', 'Active'), ('KPR_000021', 'Kirchhoff''s Current Law', 'Engineering & Technology', 'Electrical Engineering', 'Conservation Principle', 'Atomic', 'The algebraic sum of currents at a circuit node is zero, reflecting conservation of electric charge under the lumped-circuit model.', 'Applies at circuit nodes under the adopted lumped-element approximation; displacement-current effects and distributed electromagnetic behaviour may require a field-based treatment.', 'Charge conservation; node current; current balance', 'Kirchhoff''s current law provides the node-balance equation used in electrical network analysis.', 'KCL; Kirchhoff current law', 'Active'), ('KPR_000022', 'Kirchhoff''s Voltage Law', 'Engineering & Technology', 'Electrical Engineering', 'Conservation Principle', 'Atomic', 'The algebraic sum of voltage changes around a closed circuit loop is zero under the lumped-circuit approximation.', 'Applies to lumped circuits where the magnetic flux linkage and distributed electromagnetic effects are represented consistently; rapidly varying electromagnetic systems may require Maxwell-based analysis.', 'Voltage balance; loop; potential difference; energy accounting', 'The algebraic sum of voltage changes around a closed circuit loop is zero under the lumped-circuit approximation. Its valid use is bounded by: Applies to lumped circuits where the magnetic flux linkage and distributed electromagnetic effects are represented consistently; rapidly varying electromagnetic systems may require Maxwell-based analysis. Key ideas include Voltage balance; loop; potential difference; energy accounting.', 'KVL; Kirchhoff voltage law', 'Unlinked'), ('KPR_000023', 'Faraday''s Law of Electromagnetic Induction', 'Engineering & Technology', 'Electrical Engineering', 'Law', 'Atomic', 'A time-varying magnetic flux through a circuit induces an electromotive force proportional to the negative rate of change of flux linkage.', 'Applies to electromagnetic induction with the sign convention represented by Lenz''s law; circuit-level and field-level formulations must use compatible definitions of flux and induced emf.', 'Magnetic flux; induced emf; flux linkage; time variation', 'Faraday''s law connects changing magnetic flux with induced voltage and is foundational to transformers, generators, and inductive systems.', 'Faraday law; electromagnetic induction', 'Active'), ('KPR_000024', 'Lenz''s Law', 'Engineering & Technology', 'Electrical Engineering', 'Law', 'Atomic', 'The induced current or electromotive response has a direction that opposes the change in magnetic flux responsible for the induction.', 'Applies to electromagnetic induction and determines the sign/direction of induced response consistently with energy conservation.', 'Induced current; opposing change; magnetic flux; direction', 'Lenz''s law gives the directional interpretation of electromagnetic induction and is the sign principle accompanying Faraday''s law.', 'Lenz law; opposition principle', 'Active'), ('KPR_000025', 'Maximum Power Transfer Principle', 'Engineering & Technology', 'Electrical Engineering', 'Principle', 'Atomic', 'For a linear source network with fixed source parameters, maximum power is delivered to a load when the load resistance equals the source''s Thevenin resistance in a resistive network.', 'Applies to the stated source/load model and assumes the source network and load conditions represented by the theorem; reactive networks require the corresponding complex-conjugate matching condition.', 'Load matching; Thevenin resistance; delivered power; source network', 'The principle identifies the impedance-matching condition that maximizes power delivered to a specified load.', 'Maximum power transfer theorem; load matching', 'Active'), ('KPR_000026', 'Sampling Theorem', 'Engineering & Technology', 'Electrical Engineering', 'Theorem', 'Atomic', 'A band-limited continuous-time signal can be reconstructed from uniformly spaced samples when the sampling frequency is greater than twice the highest frequency present.', 'Requires the signal to be appropriately band-limited and sampling to satisfy the stated conditions; practical reconstruction also depends on filtering and implementation quality.', 'Band limitation; sampling frequency; Nyquist frequency; reconstruction', 'The sampling theorem establishes the minimum theoretical sampling rate needed to avoid aliasing for an ideal band-limited signal.', 'Nyquist-Shannon sampling theorem; sampling theorem', 'Active'), ('KPR_000027', 'Routh-Hurwitz Stability Criterion', 'Engineering & Technology', 'Mechanical Engineering; Electrical Engineering', 'Criterion', 'Atomic', 'The Routh-Hurwitz criterion determines whether all roots of a real polynomial lie in the open left half-plane using coefficients arranged in a Routh array.', 'Applies to characteristic polynomials with the conditions and coefficient structure required by the criterion; special cases such as zero rows require the established Routh procedures.', 'Characteristic polynomial; pole location; stability; Routh array', 'The criterion provides an algebraic test of continuous-time linear-system stability without explicitly solving for all polynomial roots.', 'Routh criterion; Routh-Hurwitz test', 'Active'), ('KPR_000028', 'Nyquist Stability Criterion', 'Engineering & Technology', 'Electrical Engineering; Mechanical Engineering', 'Criterion', 'Atomic', 'The Nyquist criterion determines closed-loop stability from the encirclement of critical points by the frequency response of the open-loop transfer function, together with the open-loop pole information.', 'Applies to linear feedback systems under the assumptions of the Nyquist formulation and requires correct accounting of unstable open-loop poles and encirclement direction.', 'Frequency response; encirclement; open-loop poles; closed-loop stability', 'The criterion links frequency-domain response to closed-loop stability and provides a basis for stability analysis of feedback systems.', 'Nyquist criterion; Nyquist stability test', 'Active'), ('KPR_000029', 'Bayes'' Rule', 'Engineering & Technology', 'Computer Science; Statistics; Machine Learning', 'Law', 'Atomic', 'Bayes'' rule relates a posterior probability to a likelihood, prior probability, and evidence through conditional probability.', 'Applies when the relevant conditional and marginal probabilities are defined; probability-zero evidence requires appropriate treatment and the interpretation depends on the chosen probabilistic model.', 'Conditional probability; prior; likelihood; posterior; evidence', 'Bayes'' rule provides the probability-update relationship underlying Bayesian inference, classification, diagnosis, and decision analysis.', 'Bayes rule; Bayes theorem', 'Active'), ('KPR_000030', 'CAP Theorem', 'Engineering & Technology', 'Computer Science', 'Theorem', 'Atomic', 'The CAP theorem states that a distributed data system cannot simultaneously provide all three of strong consistency, availability, and partition tolerance under a network partition.', 'Applies to distributed systems in which network partitions are possible and to the precise consistency and availability definitions used in the theorem; it is not a statement that systems can provide only two properties under all conditions.', 'Consistency; availability; partition tolerance; distributed systems', 'CAP provides a reasoning framework for understanding trade-offs in distributed data systems when partitions occur.', 'CAP theorem; consistency-availability-partition tolerance', 'Active'), ('KPR_000031', 'Byzantine Fault Tolerance Principle', 'Engineering & Technology', 'Computer Science', 'Principle', 'Atomic', 'A Byzantine fault-tolerant system must tolerate arbitrary or inconsistent component behaviour while maintaining the specified correctness properties when the fault assumptions are satisfied.', 'Applies only under explicit assumptions about the number and behaviour of faulty participants, communication model, quorum structure, and protocol guarantees.', 'Arbitrary faults; quorum; agreement; validity; fault threshold', 'The principle defines the need to preserve protocol-level safety and liveness properties despite adversarial or inconsistent component behaviour within the assumed fault model.', 'Byzantine fault tolerance; BFT principle', 'Active'), ('KPR_000032', 'End-to-End Principle', 'Engineering & Technology', 'Computer Science', 'Principle', 'Atomic', 'The end-to-end principle places functions that depend on complete application-level knowledge at the endpoints rather than relying solely on lower network layers.', 'Applies as an architectural design principle, not an absolute prohibition on lower-layer support; performance, security, reliability, and operational requirements can justify lower-layer mechanisms.', 'Layering; endpoints; application semantics; network architecture', 'The principle guides distributed and network architecture by distinguishing functions that can be implemented effectively at endpoints from those requiring network-layer support.', 'End-to-end argument; end-to-end principle', 'Active'), ('KPR_000033', 'Principle of Least Privilege', 'Engineering & Technology', 'Computer Science', 'Principle', 'Atomic', 'A subject should be granted only the minimum privileges necessary to perform its authorized tasks.', 'Applies to access-control design and should be evaluated against actual task requirements, trust boundaries, privilege inheritance, and operational constraints.', 'Authorization; minimum privilege; attack surface; access control', 'Least privilege limits the consequences of misuse or compromise by reducing unnecessary authority.', 'Least privilege; minimum necessary privilege', 'Active'), ('KPR_000034', 'Separation of Concerns Principle', 'Engineering & Technology', 'Computer Science', 'Principle', 'Atomic', 'A system should separate distinct concerns so that each concern can be reasoned about, developed, tested, and changed with limited interference from others.', 'Applies to architecture and software design; the appropriate separation depends on cohesion, coupling, interfaces, and system requirements.', 'Modularity; cohesion; coupling; concern isolation', 'Separation of concerns improves manageability by localizing responsibilities and reducing unnecessary interactions among unrelated aspects of a system.', 'Separation of concerns; SoC', 'Active'), ('KPR_000035', 'Principle of Least Action', 'Engineering & Technology', 'Mechanical Engineering', 'Principle', 'Atomic', 'The actual path of a system between specified states makes the action stationary with respect to permitted variations under the formulation of classical mechanics.', 'Applies within the variational formulation and boundary conditions of the physical system; ''stationary'' is more precise than universally describing the action as strictly minimal.', 'Action; Lagrangian; stationary variation; trajectory', 'The principle of stationary action provides a unifying variational formulation for classical mechanics and connects directly to Euler-Lagrange equations.', 'Least action; stationary action; Hamilton''s principle', 'Unlinked'), ('KPR_000036', 'Archimedes'' Principle', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Principle', 'Atomic', 'A body immersed in a fluid experiences an upward buoyant force equal to the weight of the fluid displaced by the body.', 'Applies to bodies immersed in fluids under hydrostatic assumptions appropriate to the formulation; dynamic flow effects require additional analysis.', 'Buoyancy; displaced fluid; hydrostatic pressure', 'A body immersed in a fluid experiences an upward buoyant force equal to the weight of the fluid displaced by the body. Its valid use is bounded by: Applies to bodies immersed in fluids under hydrostatic assumptions appropriate to the formulation; dynamic flow effects require additional analysis. Key ideas include Buoyancy; displaced fluid; hydrostatic pressure.', 'Archimedes principle; buoyancy principle', 'Active'), ('KPR_000037', 'Pascal''s Principle', 'Engineering & Technology', 'Mechanical Engineering', 'Principle', 'Atomic', 'A pressure change applied to a confined fluid is transmitted throughout the fluid in accordance with the hydrostatic pressure relation.', 'Applies to confined fluids under the assumptions of Pascal''s law; hydraulic-machine applications additionally require accounting for geometry, losses, and mechanical efficiency.', 'Pressure transmission; confined fluid; hydraulic amplification', 'A pressure change applied to a confined fluid is transmitted throughout the fluid in accordance with the hydrostatic pressure relation. Its valid use is bounded by: Applies to confined fluids under the assumptions of Pascal''s law; hydraulic-machine applications additionally require accounting for geometry, losses, and mechanical efficiency. Key ideas include Pressure transmission; confined fluid; hydraulic amplification.', 'Pascal law; Pascal principle', 'Active'), ('KPR_000038', 'Reynolds Similarity Principle', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering; Chemical Engineering', 'Principle', 'Atomic', 'Dynamic similarity requires corresponding dimensionless groups to be matched when comparing geometrically similar flows under the relevant governing physics.', 'Applies when the selected dimensionless groups capture the dominant physical mechanisms; matching Reynolds number alone is insufficient when other forces or transport mechanisms are significant.', 'Dynamic similarity; Reynolds number; dimensionless groups; scaling', 'Similarity principles support model testing and scale-up by identifying dimensionless conditions that preserve the dominant physical behaviour.', 'Dynamic similarity; similitude principle', 'Active'), ('KPR_000039', 'Conservation of Momentum', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering; Chemical Engineering', 'Conservation Principle', 'Atomic', 'The total linear momentum of a system changes only through the net external impulse or, in control-volume form, the net momentum flux and external forces.', 'Applies to a defined system or control volume with all relevant external forces and momentum fluxes accounted for; simplified forms require explicit assumptions.', 'Momentum balance; external force; momentum flux; impulse', 'Momentum conservation is the governing balance principle for dynamics, fluid momentum equations, jet forces, and process equipment analysis.', 'Momentum conservation; momentum-balance principle', 'Active'), ('KPR_000040', 'Conservation of Charge', 'Engineering & Technology', 'Electrical Engineering', 'Conservation Principle', 'Atomic', 'Electric charge is conserved: the net charge of an isolated system remains constant, with current representing charge transport across boundaries.', 'Applies to electromagnetic systems subject to charge continuity; circuit and field formulations must account for charge accumulation consistently.', 'Charge conservation; current; continuity equation; charge density', 'Electric charge is conserved: the net charge of an isolated system remains constant, with current representing charge transport across boundaries. Its valid use is bounded by: Applies to electromagnetic systems subject to charge continuity; circuit and field formulations must account for charge accumulation consistently. Key ideas include Charge conservation; current; continuity equation; charge density.', 'Charge conservation; charge continuity', 'Active'), ('KPR_000041', 'Principle of Effective Stress', 'Engineering & Technology', 'Civil Engineering', 'Principle', 'Atomic', 'For saturated soil under the classical effective-stress framework, the stress governing skeleton response is total stress minus pore-water pressure.', 'Applies to the assumptions of saturated soil mechanics and the adopted stress convention; partially saturated and complex multiphase systems require extended formulations.', 'Total stress; pore pressure; effective stress; soil skeleton', 'Effective stress separates total stress from pore-fluid pressure and is central to strength, consolidation, and deformation analysis.', 'Effective stress principle; Terzaghi effective stress principle', 'Active'), ('KPR_000042', 'Principle of Virtual Work', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Principle', 'Atomic', 'A body or structural system in equilibrium has zero virtual work for every kinematically admissible virtual displacement consistent with the constraints.', 'Applies to equilibrium and compatible virtual displacements under the adopted idealization; the virtual displacement is a mathematical variation, not necessarily an actual motion.', 'Equilibrium; virtual displacement; admissibility; work', 'The principle provides an alternative formulation of equilibrium and supports structural analysis, finite elements, and mechanism reasoning.', 'Virtual work principle; principle of virtual work', 'Active'), ('KPR_000043', 'Principle of Feedback', 'Engineering & Technology', 'Electrical Engineering; Mechanical Engineering', 'Principle', 'Atomic', 'Feedback uses measured or inferred system output to influence subsequent system input in order to modify system behaviour relative to a desired condition.', 'Applies to feedback architectures with explicitly defined sensing, comparison, actuation, and dynamics; feedback does not inherently guarantee stability or improved performance.', 'Feedback loop; reference; error; controller; response', 'The feedback principle is the conceptual basis for closed-loop control and regulation.', 'Feedback principle; closed-loop principle', 'Active'), ('KPR_000044', 'Separation Principle for Linear Control', 'Engineering & Technology', 'Electrical Engineering', 'Principle', 'Atomic', 'Under the conditions of the linear-quadratic-Gaussian framework, controller design and state estimation can be treated independently and then combined.', 'Applies specifically under the assumptions of the LQG formulation; it should not be generalized to arbitrary nonlinear, constrained, or non-Gaussian control problems.', 'LQG; state estimation; controller design; separation', 'The separation principle simplifies LQG design by allowing estimator and controller components to be designed independently under the stated assumptions.', 'LQG separation principle; LQG; state estimation; controller design; separation', 'Active'), ('KPR_000045', 'Principle of Mass Transfer Driving Force', 'Engineering & Technology', 'Chemical Engineering', 'Principle', 'Atomic', 'Mass-transfer rate is driven by a difference between the actual state and an appropriate equilibrium or reference state, with resistance or transfer coefficients relating the driving force to flux.', 'Applies to the selected mass-transfer representation and phase-equilibrium assumptions; the definition of driving force depends on the chosen concentration, partial-pressure, fugacity, or other basis.', 'Driving force; equilibrium; transfer coefficient; resistance', 'The driving-force principle provides the conceptual basis for film, resistance, and overall mass-transfer formulations.', 'Mass-transfer driving force principle; Driving force; equilibrium; transfer coefficient; resistance', 'Active'), ('KPR_000046', 'Principle of Thermal Resistance', 'Engineering & Technology', 'Mechanical Engineering; Chemical Engineering', 'Principle', 'Atomic', 'For one-dimensional steady conduction or analogous linear heat-transfer paths, heat-transfer rate is proportional to the temperature difference divided by the total thermal resistance.', 'Applies to linearized, steady heat-transfer networks where resistances can be defined consistently; contact, radiation, and nonlinear conductivity may require modified representations.', 'Temperature difference; thermal resistance; heat-transfer rate; series/parallel resistance', 'For one-dimensional steady conduction or analogous linear heat-transfer paths, heat-transfer rate is proportional to the temperature difference divided by the total thermal resistance. Its valid use is bounded by: Applies to linearized, steady heat-transfer networks where resistances can be defined consistently; contact, radiation, and nonlinear conductivity may require modified representations. Key ideas include Temperature difference; thermal resistance; heat-transfer rate; series/parallel resistance.', 'Thermal resistance principle; resistance-network method', 'Active'), ('KPR_000047', 'Principle of Dimensional Homogeneity', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering; Chemical Engineering', 'Principle', 'Atomic', 'A physically meaningful engineering equation must be dimensionally homogeneous, with quantities on each additive side expressed in compatible dimensions.', 'Applies to equations representing physical quantities; dimensional consistency is necessary but does not by itself establish physical correctness.', 'Dimensions; units; dimensional consistency; scaling', 'Dimensional homogeneity provides a basic validation rule for physical equations and supports dimensional analysis.', 'Principle of dimensional homogeneity; dimensional consistency', 'Active'), ('KPR_000048', 'Buckingham Pi Theorem', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering; Chemical Engineering', 'Theorem', 'Atomic', 'A dimensionally homogeneous physical relationship involving a specified set of dimensional variables can be represented using a reduced number of independent dimensionless groups.', 'Applies when the variables and fundamental dimensions are correctly identified and the dimensional matrix has the required rank.', 'Dimensionless groups; dimensional matrix; variable reduction; similarity', 'The theorem provides the formal foundation for dimensional analysis and the construction of dimensionless correlations.', 'Buckingham Pi theorem; Pi theorem', 'Active'), ('KPR_000049', 'Principle of Minimum Potential Energy', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Principle', 'Atomic', 'For a stable conservative elastic system under appropriate constraints, the equilibrium configuration corresponds to a local minimum of total potential energy.', 'Applies to conservative systems and stable equilibrium configurations within the adopted elastic model; unstable equilibria are not minima.', 'Potential energy; equilibrium; stability; conservative system', 'The principle provides an energy-based formulation of equilibrium and is widely used in structural mechanics and variational methods.', 'Minimum potential energy principle; Potential energy; equilibrium; stability; conservative system', 'Active'), ('KPR_000050', 'Principle of Virtual Displacements', 'Engineering & Technology', 'Civil Engineering; Mechanical Engineering', 'Principle', 'Atomic', 'For a system in static equilibrium, the total virtual work of external and internal forces is zero for every admissible virtual displacement.', 'Applies to static equilibrium under compatible virtual displacements and the adopted idealization.', 'Virtual displacement; equilibrium; internal work; external work', 'The principle converts equilibrium into a variational statement useful for structural analysis and finite-element formulations.', 'Virtual displacement principle; virtual work formulation', 'Active') ON CONFLICT DO NOTHING;